package harness

import (
	"encoding/json"
	"errors"
	"net/url"
	"slices"
	"strconv"
	"strings"

	api "github.com/andrewmccall/sproozi/api/v1alpha1"
)

const (
	fixtureMCPName    = "docs"
	nativeHTTPScheme  = "https"
	nativeEntryName   = "name"
	nativeContextName = "sproozi"
)

// NativeClientConfig is regenerated by the trusted placement for each launch.
// It contains broker connections and a credential-free Kubernetes client binding,
// never upstream endpoints, credentials, or configuration from a checkpoint.
type NativeClientConfig struct {
	Kubernetes bool     `json:"kubernetes,omitempty"`
	MCPGateway string   `json:"mcpGateway,omitempty"`
	MCPServers []string `json:"mcpServers,omitempty"`
}

func (c *NativeClientConfig) Validate(kind NativeKind) error {
	if c == nil {
		return nil
	}
	if len(c.MCPServers) > 32 {
		return errors.New("native MCP connection count exceeded")
	}
	if len(c.MCPServers) == 0 {
		if c.MCPGateway != "" {
			return errors.New("native MCP gateway without connections")
		}
		return nil
	}
	if kind != NativeCodex {
		return errors.New("managed native MCP currently requires Codex")
	}
	u, err := url.Parse(c.MCPGateway)
	if err != nil || u.Scheme != nativeHTTPScheme || u.Host == "" || u.User != nil || u.Path != "" || u.RawQuery != "" || u.ForceQuery || u.Fragment != "" {
		return errors.New("native MCP requires exact broker HTTPS authority")
	}
	seen := map[string]bool{}
	for _, name := range c.MCPServers {
		if _, valid := api.CapabilityKind("mcp." + name).MCPServerName(); !valid || seen[name] {
			return errors.New("invalid or duplicate native MCP server")
		}
		seen[name] = true
	}
	return nil
}

// CodexOptions returns only the approved broker connections. These trusted
// overrides follow administrator options so portable personal settings cannot
// replace the installed connection.
func (c *NativeClientConfig) CodexOptions() []string {
	if c == nil {
		return nil
	}
	names := slices.Clone(c.MCPServers)
	slices.Sort(names)
	options := make([]string, 0, 2*len(names))
	for _, name := range names {
		key := "mcp_servers." + name
		options = append(options, key+".url="+strconv.Quote(c.MCPGateway+"/mcp/"+name), key+".required=true")
	}
	return options
}

// NativeKubeconfig targets the inspected authority through the authenticated
// proxy. The inner token is a public placeholder stripped by the gateway.
func NativeKubeconfig(trustPath string) string {
	document := map[string]any{
		"apiVersion": "v1", "kind": "Config", "current-context": nativeContextName,
		"clusters": []any{map[string]any{nativeEntryName: nativeContextName, "cluster": map[string]any{"server": "https://kubernetes.default.svc", "certificate-authority": trustPath}}},
		"users":    []any{map[string]any{nativeEntryName: nativeContextName, claudeUser: map[string]any{"token": "sproozi-worker-placeholder"}}},
		"contexts": []any{map[string]any{nativeEntryName: nativeContextName, "context": map[string]any{"cluster": nativeContextName, claudeUser: nativeContextName}}},
	}
	data, _ := json.Marshal(document)
	return strings.TrimSpace(string(data)) + "\n"
}

// NativeClients renders only the declared broker capabilities. Backend callers
// supply their trusted gateway origin, never checkpoint-provided configuration.
func NativeClients(kind NativeKind, capabilities []api.CapabilityKind, gateway string) (*NativeClientConfig, error) {
	config := &NativeClientConfig{}
	for _, capability := range capabilities {
		if capability == api.CapabilityKubernetesRead {
			config.Kubernetes = true
		}
		if name, ok := capability.MCPServerName(); ok {
			config.MCPServers = append(config.MCPServers, name)
		}
	}
	if len(config.MCPServers) != 0 {
		config.MCPGateway = gateway
		slices.Sort(config.MCPServers)
	}
	if err := config.Validate(kind); err != nil {
		return nil, err
	}
	if !config.Kubernetes && len(config.MCPServers) == 0 {
		return nil, nil
	}
	return config, nil
}
